<script setup>
import {ref,computed,onMounted,nextTick} from 'vue'
import {request} from './client'
import Icon from '../Icon.vue'
import ProviderOverview from './ProviderOverview.vue'
import ProviderMetrics from './ProviderMetrics.vue'
import ClassroomHandovers from './ClassroomHandovers.vue'
import MembershipMail from './MembershipMail.vue'
import {teachingTeam,invitationResponseLabel} from './teachingTeam.js'
const props=defineProps({member:Object,institute:Object,teamOnly:Boolean}),emit=defineEmits(['navigate','create','room'])
const instituteTeacher=computed(()=>props.member.institute_teacher===true)
const metricsError=ref(''),teamSection=ref(null)
async function openTeam(){showTeam.value=true;await nextTick();teamSection.value?.scrollIntoView({behavior:'smooth',block:'start'})}
const needsProfile=computed(()=>error.value==='Verify the institute profile first')
const metrics=ref(null),showTeam=ref(false),teamQuery=ref(''),teamFilter=ref('All')
const invitations=ref([])
const team=computed(()=>admin.value?teachingTeam(data.value?.memberships||[],invitations.value):(data.value?.memberships||[]))
const filteredTeam=computed(()=>team.value.filter(l=>(teamFilter.value==='All'||l.status===teamFilter.value)&&[l.person?.display_name,l.person?.username,l.user].some(v=>String(v||'').toLowerCase().includes(teamQuery.value.trim().toLowerCase()))))
const data=ref(null),error=ref(''),busy=ref(false),decision=ref(null)
const admin=computed(()=>props.member.role==='Admin'),pending=computed(()=>data.value?.memberships.filter(l=>l.status==='Pending')||[])
const money=n=>new Intl.NumberFormat('en-LK',{maximumFractionDigits:0}).format(n)
async function load(){error.value='';metricsError.value='';try{const [overview,invites]=await Promise.all([request('teaching','overview'),admin.value?request('invitations','list_invitations'):Promise.resolve([])]);data.value=overview;invitations.value=invites;data.value.memberships.sort((a,b)=>(b.status==='Pending')-(a.status==='Pending'))}catch(e){error.value=e.message;return}if(instituteTeacher.value){metrics.value=null;return}try{metrics.value=await request('commercial','metrics')}catch(e){metrics.value=null;metricsError.value='Your teaching overview is ready. Reports could not load. Please try again.'}}
async function act(link,status){busy.value=true;error.value='';try{await request('teaching','membership',{name:link.name,status});decision.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function date(value){return value?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(value).replace(' ','T')+'+05:30')):'—'}
const statusLabel=l=>({Active:'Member',Pending:'Request to join',Invited:'Invitation pending',Rejected:'Rejected',Disconnected:'Not connected'})[l.status]||l.status
onMounted(load)
</script>
<template><section class="provider-home"><div class="page-heading"><div><span class="eyebrow">GOOD TEACHING STARTS WITH A LITTLE CLARITY</span><h1>{{teamOnly?'Teaching team':admin?'Institute overview':'Hello, '+member.full_name.split(' ')[0]+'.'}}</h1><p>{{teamOnly?'Review requests, invite teachers and manage your institute’s teaching team.':admin?'Your people, programmes and class fees. All in one place.':instituteTeacher?'Your assigned classes, learners and schedule at '+institute.title+'.':'Your independent classes, learners, schedule and collections.'}}</p></div><div class="heading-actions"><slot name="actions"/><button v-if="!teamOnly&&!needsProfile&&!instituteTeacher" class="button primary" @click="emit('create')"><Icon name="Plus" :size="17"/>{{admin?'Create institute class':'Create personal class'}}</button></div></div><section v-if="needsProfile" class="profile-next-step" role="status"><span class="setup-symbol"><Icon name="Building2" :size="28"/></span><div><span class="eyebrow">LET’S GET YOUR INSTITUTE READY</span><h2>Complete your institute profile</h2><p>Add your institute’s details and submit them for verification. Your teaching overview will be available once the profile is verified.</p><button class="button primary" @click="emit('navigate','profile')">Open institute profile <Icon name="ArrowRight" :size="17"/></button><button class="text-button" @click="load">Check verification status</button></div></section><p v-else-if="error" class="error" role="alert">{{error}}</p><p v-if="!data&&!error">Opening your workspace…</p><template v-if="data"><ClassroomHandovers v-if="admin||instituteTeacher" :admin="admin" @changed="load"/>
<template v-if="!teamOnly"><ProviderOverview :data="data" :metrics="metrics" :admin="admin" :member="member" @navigate="emit('navigate',$event)" @room="emit('room',data.classrooms.find(r=>r.name===$event))" @team="openTeam"/><section v-if="instituteTeacher" class="panel" style="padding:24px;margin-bottom:24px"><h2>Your institute manages the workspace</h2><p>Institute subscriptions and class payments are managed by your institute. Open an assigned classroom to use the teaching tools available to you.</p></section><template v-else><p v-if="metricsError" role="status">{{metricsError}} <button class="text-button" @click="load">Retry reports</button></p><ProviderMetrics v-if="metrics" :source="metrics" :institute="admin"/></template><button class="button subtle team-toggle" @click="showTeam=!showTeam">{{showTeam?'Hide':'Manage'}} {{admin?'teaching team & invitations':'institute memberships'}} <Icon name="ChevronDown" :size="16"/></button></template><div v-if="teamOnly||showTeam" ref="teamSection">
<MembershipMail :member="member" :hide-history="admin" @changed="load"/><div class="section-heading"><div><h2>{{admin?'Teachers & requests':'Your institute memberships'}}</h2><p>{{admin?'Invitations, responses and memberships — one card for each teacher.':'Keep institute work and personal classes side by side.'}}</p></div><button v-if="admin" class="button subtle" :disabled="busy" @click="load"><Icon name="RefreshCw" :size="16"/>Refresh team</button><button v-else class="button subtle" @click="emit('navigate',member.unified_teacher?'join-institute':'connections')">Find an institute</button></div><div v-if="admin" class="team-toolbar"><div class="tabs" aria-label="Teacher membership status"><button v-for="filter in [{value:'All',label:'All teachers'},{value:'Pending',label:'Requests'},{value:'Active',label:'Members'},{value:'Invited',label:'Invited'},{value:'Rejected',label:'Rejected'}]" :key="filter.value" :class="{selected:teamFilter===filter.value}" :aria-pressed="teamFilter===filter.value" @click="teamFilter=filter.value">{{filter.label}}<span class="team-count">{{filter.value==='All'?team.length:team.filter(l=>l.status===filter.value).length}}</span></button></div><label class="search"><Icon name="Search" :size="18"/><input v-model="teamQuery" type="search" aria-label="Search teaching team" placeholder="Search name, username or email"></label></div><div class="provider-team"><article v-for="l in filteredTeam" :key="l.name" class="panel team-card"><img v-if="l.person?.cover_image" class="team-cover" :src="l.person.cover_image" alt=""><div class="team-content"><span v-if="!l.person?.profile_image" class="team-placeholder"><Icon name="GraduationCap" :size="25"/></span><img v-if="l.person?.profile_image" :src="l.person.profile_image" class="team-face" alt=""><span class="badge" :class="l.status==='Active'?'green':['Pending','Invited'].includes(l.status)?'amber':'team-status-history'">{{statusLabel(l)}}</span><h3>{{l.person?.display_name||l.user||l.profile}}</h3><p v-if="l.person?.qualifications&&!['none','null'].includes(String(l.person.qualifications).toLowerCase())">{{l.person.qualifications}}</p><small v-if="l.person?.username">@{{l.person.username}}</small><p v-if="admin&&l.person&&l.user" class="team-email">{{l.user}}</p><div v-if="l.invitations?.length" class="team-invitation-details"><dl><div><dt>Invitation sent</dt><dd>{{date(l.invitations[0].creation)}}</dd></div><div><dt>{{invitationResponseLabel(l.invitations[0])}}</dt><dd>{{date(l.invitations[0].responded_at||l.invitations[0].expires_at)}}</dd></div></dl><small v-if="l.invitations[0].email_status" class="team-delivery"><Icon name="Mail" :size="13"/>{{l.invitations[0].email_status}}</small><details v-if="l.invitations.length>1" class="team-invitation-history"><summary>Earlier invitations ({{l.invitations.length-1}})</summary><div v-for="invite in l.invitations.slice(1)" :key="invite.name"><strong>{{invite.status==='Declined'?'Rejected':invite.expired?'Expired':invite.status}}</strong><small>Sent {{date(invite.creation)}}</small><small v-if="invite.responded_at">{{invitationResponseLabel(invite)}} {{date(invite.responded_at)}}</small></div></details></div><p v-if="l.status==='Pending'" class="team-request-note">Waiting for your review</p><div v-if="['Active','Pending'].includes(l.status)" class="team-actions"><template v-if="admin&&l.status==='Pending'"><button class="button primary small" :disabled="busy" @click="act(l,'Active')">Accept teacher</button><button class="text-button" :disabled="busy" @click="act(l,'Rejected')">Decline</button></template><button v-else class="text-button" @click="decision=l">{{admin?'Remove from institute':'Leave institute'}}</button></div></div></article><div v-if="!filteredTeam.length" class="empty-state team-empty"><Icon name="Users"/><h3>{{team.length?'No matching teachers':'Your team starts here'}}</h3><p>{{team.length?'Try another name or membership status.':'Invite a teacher by email. Requests and approved teachers will appear here.'}}</p><button v-if="teamQuery||teamFilter!=='All'" class="button subtle" @click="teamQuery='';teamFilter='All'">Clear team filters</button></div></div>
<section v-if="decision" class="panel membership-confirm" role="alert"><h3>{{admin?'Remove teacher membership?':'Leave this institute?'}}</h3><p>This ends access to the institute’s class assignments. The teacher’s account and personal classes remain available.</p><button class="button primary" :disabled="busy" @click="act(decision,admin?'Removed':'Left')">Confirm {{admin?'removal':'leave'}}</button><button class="button subtle" @click="decision=null">Keep membership</button></section>
</div></template></section></template>
<style>.team-toggle{margin:8px 0 24px}.provider-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:26px}.provider-metrics article{padding:24px;display:flex;flex-direction:column;gap:14px}.provider-metrics span{font-size:12px}.provider-metrics strong{font-size:38px;font-weight:650;color:#8163a1}.provider-metrics small{font-size:10px;line-height:1.6;color:var(--student-muted)}.provider-columns{display:grid;grid-template-columns:1.4fr 1fr;gap:24px;margin-bottom:38px}.academy-feature{background:linear-gradient(125deg,rgb(108 106 238 / 8%),rgb(108 106 238 / 12%) 58%,#f4e7ed);border:1px solid rgb(108 106 238 / 12%);border-radius:27px;padding:36px;display:flex;gap:24px;align-items:center;overflow:hidden;color:#554465}.academy-feature h2{font-size:29px;line-height:1.3;margin:18px 0}.academy-feature p{line-height:1.8;font-size:13px;margin-bottom:24px}.programme-art{font-size:80px;display:flex;flex-direction:column;align-items:center;color:#6C6AEE;transform:rotate(-7deg);min-width:120px}.programme-art span{font-family:Georgia,serif;font-size:28px;line-height:1.1;color:#826195}.fee-summary{padding:28px}.fee-summary h2{font-size:22px;margin:15px 0}.fee-summary p{font-size:12px;line-height:1.8;margin-bottom:15px}.fee-total{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--student-border);font-size:12px}.fee-summary .text-button{margin-top:18px}.provider-team{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.team-card{overflow:hidden}.team-cover{width:100%;aspect-ratio:2.8;object-fit:cover}.team-content{padding:0 20px 22px}.team-face{width:70px;height:70px;border:4px solid var(--student-card,#fff);border-radius:50%;object-fit:cover;margin-top:-32px;position:relative;display:block;margin-bottom:12px}.team-content h3{font-size:17px;line-height:1.5;margin:12px 0 7px}.team-content p,.team-content small{font-size:11px;line-height:1.8;color:var(--student-muted)}.team-actions{margin-top:20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.membership-confirm{position:sticky;bottom:20px;padding:25px;box-shadow:0 10px 60px #5e3f6230}.membership-confirm p{margin:16px 0}.membership-confirm button{margin-inline-end:10px}@media(max-width:1150px){.provider-team{grid-template-columns:repeat(3,1fr)}.provider-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.provider-columns{grid-template-columns:1fr}.provider-team{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.provider-team{grid-template-columns:1fr}.provider-metrics article{padding:18px}.academy-feature{padding:26px}.programme-art{display:none}}</style>

<style scoped>.profile-next-step{display:flex;gap:24px;padding:32px;border:1px solid var(--student-border,#e5def0);border-radius:20px;background:var(--student-card,#faf8ff);max-width:900px}.setup-symbol{color:#6c4ba0;background:#eee7fa;border-radius:16px;padding:16px;height:fit-content}.profile-next-step h2{font-size:24px;margin:12px 0}.profile-next-step p{line-height:1.7;margin:0 0 24px;color:var(--student-muted,#655b75)}.profile-next-step button{margin:0 12px 12px 0}@media(max-width:600px){.profile-next-step{padding:24px;flex-direction:column}}</style>

<style scoped>.heading-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}</style>

<style scoped>
.team-invitation-details{margin-top:18px;padding-top:16px;border-top:1px solid #e7deef}.team-invitation-details dl{display:grid;gap:13px;margin:0 0 14px}.team-invitation-details dt{font-size:11px;color:#776786;margin-bottom:5px}.team-invitation-details dd{margin:0;font-size:12px;color:#40304e;font-weight:600;line-height:1.7}.team-content .team-email{overflow-wrap:anywhere;margin:8px 0}.team-content h3{overflow-wrap:anywhere}.team-delivery{display:flex;align-items:center;gap:7px}.team-status-history{background:#f4eaf0;color:#8a3854}.team-invitation-history{margin-top:14px;font-size:12px}.team-invitation-history summary{cursor:pointer;color:#592c91;padding:8px 0}.team-invitation-history>div{padding:10px 0;border-top:1px solid #eee8f2}.team-invitation-history small{display:block}.team-toolbar .tabs{flex-wrap:wrap}
</style>
